<?php	/**	* Fecha: 21/11/2013	* Descripción: Libreria de variables utilizadar en DataTableServer.php. 	* Comentarios: En este archivo se define el estilo que utilizará una columna dado el valor que obtuvo	* de la consulta	* 	* $Record=Fila actual	* $IndexColumn=Indice del registro (ID)	* $TableConfig['Columns'][$i]=Valor de la columna.	**/	if($ColumRender == 'Icon'){		$Render['Icon'] = '<div align="center"><i class="fa-lg ' . $Record[$ColumName] . '"></i></div>';	}	if($ColumRender == 'Contrasena'){		$Render['Contrasena'] =   '<div class="w-100 text-center"><p id="Pass'. $Record[$IndexColumn] . '" class="d-none">' . $Record[$ColumName] . '</p><button class="clipboard fa fa-lock btn btn-primary btn-md zeroclipboard-is-hover" data-clipboard-text="' . $Record[$ColumName] . '" id="button-copy-password" onclick="copyToClipboard(`#Pass'. $Record[$IndexColumn] . '`)" title="Copiar Contraseña" data-toggle="popover" data-placement="right" data-trigger="focus" data-content="La Contraseña ha sido copiada" data-original-title="Copiar Contraseña"></button></div>';	}	if($ColumRender == 'Pricing'){		$Decimals = (isset($TableConfig['Decimals']) ? $TableConfig['Decimals']:2);		$Render['Pricing'] = '<div align="right">$' . (!empty($Record[$ColumName]) ? (number_format($Record[$ColumName], $Decimals)):'-') . '</div>';	}	if($ColumRender == 'NumberFormat'){		$Decimals = (isset($TableConfig['Decimals']) ? $TableConfig['Decimals']:2);		$Render['NumberFormat'] = '<div align="right">' . (!empty($Record[$ColumName]) ? (number_format($Record[$ColumName], $Decimals)):number_format(0, $Decimals)) . '</div>';	}	if($ColumRender == 'Fecha'){		if($Record[$ColumName]){			$Render['Fecha'] = '<div class="text-center">' . ucwords(strftime('%d %h %Y', strtotime($Record[$ColumName]))) . '</div>';		}else{			$Render['Fecha'] = '';		}	}	if($ColumRender == 'FechaHora'){		if($Record[$ColumName]){			$Render['FechaHora'] = '<div class="text-center">' . ucwords(strftime('%d %h %Y %H:%M:%S', strtotime($Record[$ColumName]))) . '</div>';		}else{			$Render['FechaHora'] = '';		}	}	if($ColumRender == 'Boolean'){		$Render['Boolean'] = '<div align="center">' . (intval($Record[$ColumName]) == 1 ? 'SI':'NO') . '</div>';	}	if($ColumRender == 'NombreD_ia'){		switch($Record[$ColumName]){			case 0:				$Render['NombreD_ia'] = 'DOMINGO';				break;			case 1:				$Render['NombreD_ia'] = 'LUNES';				break;			case 2:				$Render['NombreD_ia'] = 'MARTES';				break;			case 3:				$Render['NombreD_ia'] = 'MIERCOLES';				break;			case 4:				$Render['NombreD_ia'] = 'JUEVES';				break;			case 5:				$Render['NombreD_ia'] = 'VIERNES';				break;			case 6:				$Render['NombreD_ia'] = 'SABADO';				break;		}	}	if($ColumRender == 'LinkPreview'){		$Render['LinkPreview'] =    '<div class="text-center">' .										'<a href="' . $MyTable . '?' . EncodeThis('Action=VistaPrevia&Key=' . $Record[$IndexColumn]) . '">' . $Record[$ColumName] . '</a>' .									'</div>';	}	if($ColumRender == 'LinkMenu'){		if(isset($Record['TipoDeElemento']) && $Record['TipoDeElemento'] == 4) {			$Render['LinkMenu'] =   '<div class="text-left">' .				'<a href="CelaRepositorio?' . EncodeThis('Action=VistaPrevia&Key=' . $Record[$ColumName]) . '" target="_blank">Ver Archivo</a>' .				'</div>';		}else {			$Render['LinkMenu'] =   '<div class="text-left">' .				'<a href="' . str_replace('.php', '', $Record[$ColumName]) . '" target="_blank">' . $Record[$ColumName] . '</a>' .				'</div>';		}	}	if($ColumRender == 'IndexDelete'){		$Render['IndexDelete'] =    '<div align="center">'.$Record[$IndexColumn] .										'<div style="display: none; width: 500px; position: absolute; margin-left: 50px;" align="left" id="Actions_' . $Record[$IndexColumn] . '">' .											(isset($Privilegios['Eliminar']) && $Privilegios['Eliminar'] == 1 ?											'<a class="btn btn-xs btn-danger delete" href="' . $MyTable . 'Eliminar?' . EncodeThis('Key[]=' . $Record[$IndexColumn]) . '" title="Eliminar" >' .												'<i class="fa fa-trash-alt"></i>&nbsp; Eliminar' .											'</a>&nbsp;':'').										'</div>'.									'</div>';	}	if($ColumRender == 'DownloadFile'){		if($Record[$ColumName]!=''){			$Render['DownloadFile'] =   '<div align="center">' .											'<a class="btn btn-primary btn-sm" href="CelaRepositorio?'.EncodeThis('Action=Descargar&Key=' . $Record[$ColumName]) . '" title="Descargar documento" >' .												'<i class="fa fa-file-pdf-o"></i>&nbsp; Descargar'.											'</a>' .										'</div>';		}else{			$Render['DownloadFile'] = '';		}	}	if($ColumRender == 'DownloadPreviewFile'){		if($Record[$ColumName]!=''){			$Render['DownloadPreviewFile'] =    '<div align="center">'.													'<a class="btn btn-primary btn-sm" href="CelaRepositorio?' . EncodeThis('Action=Descargar&Key=' . $Record[$ColumName]) . '" title="Descargar documento" >' .														'<i class="fa fa-download"></i>'.													'</a>' .													'&nbsp;' .													'<a class="btn btn-info btn-sm " id="' . $Record[$ColumName] . '" target="_blank" href="CelaRepositorio?' . EncodeThis('Action=VistaPrevia&Key=' . $Record[$ColumName]) . '" title="Vista																						previa del documento" >' .														'<i class="fa fa-eye"></i>' .													'</a>' .												'</div>';		}else{			$Render['DownloadPreviewFile'] = '';		}	}	if($ColumRender == 'ShowImage'){		$Render['ShowImage'] = '' .			'<a href="' . $Record[$ColumName] . '">				<img alt="" class="img-polaroid" src="' . $Record[$ColumName] . '" height="60px">			</a>';	}		if($ColumRender == 'DownloadPreviewFileWhitpdf'){				/*Se busca el archivo pdf*/		$idPdf = GetValue(sprintf('SELECT id FROM CelaRepositorio WHERE Nombre = %s;', GetSQLValueString(str_replace(array(strtolower('XML'), strtoupper('XML')), 'pdf', $Record['NombreRepo']), 'varchar')), 'id');				$Render['DownloadPreviewFileWhitpdf'] =   '' .			'<div align="center">' .			'<a class="btn btn-sm btn-success" title="Descargar" href="CelaRepositorio?' . EncodeThis('Key=' . $Record[$IndexColumn] . '&Action=Descargar') . '" data-index="' . $Record[$IndexColumn] . '">' .			'<i class="fa fa-download"></i>&nbsp;' .			'</a>&nbsp;' .			'<a  class="btn btn-sm btn-info" id="' . $Record[$IndexColumn] . '" title="Vista Previa" href="CelaRepositorio?' . EncodeThis("Key=" . $Record[$IndexColumn] . '&Action=VistaPrevia') . '" data-index="' . $Record[$IndexColumn] . '">' .			'<i class="fa fa-eye"></i>&nbsp;' .			'</a>&nbsp;<a class="btn btn-sm btn-danger" id="' . $Record[$IndexColumn] . '" title="Vista Previa" href="CelaRepositorio?' . EncodeThis("Key=" . $idPdf . '&Action=VistaPrevia') . '" data-index="' . $idPdf . '"><i class="fa fa-file-pdf"></i>' .				'</a>&nbsp;' .			'</div>';	}		if($ColumRender == 'LinkNomina'){		$Render['LinkNomina'] =   '<a href="Nomina?' . EncodeThis('RFC=' . $Record['RFC'] . '&Periodo=' . $Record['Periodo'] . '&Status[]=VACACIONES&Status[]=DESCUENTOS MAYORES AL INGRESO&Status[]=SI TIMBRADO&Process=0') . '">' . $Record[$ColumName] . '</a>';	}?>